143				{error}
144			</div>
145		{/if}
146	
147		<!-- Loading skeleton -->
148		{#if loading}
149			<SessionStreamSkeleton />
150		{:else if session}
151			<!-- Main content: context panel + stream -->
152			<div class="flex flex-1 min-h-0">
153				<!-- AC: @ui-session-stream ac-4 — Context panel with spec context, files, budget -->
154				<SessionContextPanel {session} {blocks} />
155	
156				<!-- AC: @ui-session-stream ac-1, ac-2, ac-3 — Event stream -->
157				<SessionStream {blocks} {isLive} {streamingText} />
158			</div>
159		{/if}
160	</div>
161	
162	<style>
163		@keyframes session-pulse {
