  5	<script lang="ts">
  6		import { type DisplayBlock, shouldAutoScroll as computeShouldAutoScroll, shouldShowJumpButton as computeShowJumpButton } from './session-utils';
  7		import MessageBlock from './MessageBlock.svelte';
  8		import ToolCallView from './ToolCallView.svelte';
  9		import ThinkingBlock from './ThinkingBlock.svelte';
