 12	
 13		let {
 14			blocks,
 15			isLive = false,
 16			streamingText = '',
 17		}: {
 18			blocks: DisplayBlock[];
 19			isLive?: boolean;
 20			streamingText?: string;
 21		} = $props();
 22	
 23		let scrollContainer: HTMLDivElement | undefined = $state();
 24		let autoScrollActive = $state(true);
 25		let userScrolling = $state(false);
