  1	/**
  2	 * Session API Routes
  3	 *
  4	 * REST endpoints for session data:
  5	 * - GET /api/sessions - list sessions with summaries
  6	 * - GET /api/sessions/:id - get session metadata and detail
  7	 * - GET /api/sessions/:id/events - get session events from events.jsonl
  8	 *
  9	 * AC Coverage:
 10	 * - @ui-session-stream ac-1: Session events as structured blocks
 11	 * - @ui-session-stream ac-4: Session metadata, spec context, budget for context panel
 12	 */
 13	
 14	import { Elysia, t } from 'elysia';
 15	import {
 16	  getSession,
 17	  listSessions,
 18	  readEvents,
 19	  deduplicatePhasedToolCalls,
 20	  getSessionLogSummary,
 21	  getAllSessionLogSummaries,
 22	  resolveSessionId,
 23	  getBudget,
 24	} from '../../sessions/store.js';
 25	import {
 26	  initContext,
 27	  loadAllTasks,
 28	  loadAllItems,
 29	  ReferenceIndex,
 30	} from '../../parser/index.js';
 31	
 32	export function createSessionRoutes() {
 33	  return new Elysia({ prefix: '/api/sessions' })
 34	
 35	    // List all sessions with summaries
 36	    .get('/', async ({ projectContext }) => {
 37	      const ctx = await initContext(projectContext.path);
 38	      const summaries = await getAllSessionLogSummaries(ctx.specDir);
 39	
 40	      // Sort by started_at descending (most recent first)
 41	      summaries.sort((a, b) =>
 42	        new Date(b.started_at).getTime() - new Date(a.started_at).getTime()
 43	      );
 44	
 45	      return {
 46	        items: summaries,
 47	        total: summaries.length,
 48	      };
 49	    })
 50	
 51	    // Get single session metadata
 52	    // AC: @ui-session-stream ac-4 — Includes spec context, budget, and task info
 53	    .get('/:id', async ({ params, error: errorResponse, projectContext }) => {
 54	      const ctx = await initContext(projectContext.path);
 55	
 56	      // Resolve session ID (supports prefix matching)
 57	      const resolution = await resolveSessionId(ctx.specDir, params.id);
 58	      if (!resolution.ok) {
 59	        if (resolution.error === 'ambiguous') {
 60	          return errorResponse(400, {
 61	            error: 'ambiguous_id',
 62	            message: `Ambiguous session ID: ${params.id} matches ${resolution.matches.length} sessions`,
 63	            suggestion: 'Provide a longer prefix to uniquely identify the session',
 64	          });
 65	        }
 66	        return errorResponse(404, {
 67	          error: 'not_found',
 68	          message: `Session not found: ${params.id}`,
 69	          suggestion: 'Use GET /api/sessions to list available sessions',
 70	        });
 71	      }
 72	
 73	      const detail = await getSessionLogSummary(ctx.specDir, resolution.id);
 74	      if (!detail) {
 75	        return errorResponse(404, {
 76	          error: 'not_found',
 77	          message: `Session not found: ${params.id}`,
 78	          suggestion: 'Use GET /api/sessions to list available sessions',
 79	        });
 80	      }
 81	
 82	      const metadata = await getSession(ctx.specDir, resolution.id);
 83	
 84	      // AC: @ui-session-stream ac-4 — Resolve spec context from task's spec_ref
 85	      let spec_context: {
 86	        spec_ref: string;
 87	        title: string;
 88	        acceptance_criteria: Array<{ id: string; description: string }>;
 89	      } | null = null;
 90	
 91	      if (metadata?.task_id) {
 92	        try {
 93	          const tasks = await loadAllTasks(ctx);
 94	          const items = await loadAllItems(ctx);
 95	          const index = new ReferenceIndex(tasks, items);
 96	          const taskResult = index.resolve(metadata.task_id);
 97	          if (taskResult.ok) {
 98	            const task = taskResult.item as { spec_ref?: string };
 99	            if (task.spec_ref) {
100	              const specResult = index.resolve(task.spec_ref);
101	              if (specResult.ok) {
102	                const specItem = specResult.item as {
103	                  title: string;
104	                  acceptance_criteria?: Array<{ description?: string; given?: string }>;
105	                };
106	                spec_context = {
107	                  spec_ref: task.spec_ref,
108	                  title: specItem.title,
109	                  acceptance_criteria: (specItem.acceptance_criteria ?? []).map((ac, i) => ({
110	                    id: `ac-${i + 1}`,
111	                    description: ac.description ?? ac.given ?? '',
112	                  })),
113	                };
114	              }
115	            }
116	          }
117	        } catch {
118	          // Non-critical — spec context is optional
119	        }
120	      }
121	
122	      // AC: @ui-session-stream ac-4 — Include budget info
123	      let budget: { max_per_cycle: number; started_this_cycle: number } | null = null;
124	      try {
125	        budget = await getBudget(ctx.specDir, resolution.id);
126	      } catch {
127	        // No budget configured — that's fine
128	      }
129	
130	      return {
131	        ...detail,
132	        task_id: metadata?.task_id,
133	        agent_id: metadata?.agent_id,
134	        trigger: metadata?.trigger ?? 'legacy',
135	        spec_context,
136	        budget,
137	      };
138	    })
139	
140	    // Get session events
141	    .get('/:id/events', async ({ params, query, error: errorResponse, projectContext }) => {
142	      const ctx = await initContext(projectContext.path);
143	
144	      const resolution = await resolveSessionId(ctx.specDir, params.id);
145	      if (!resolution.ok) {
146	        if (resolution.error === 'ambiguous') {
147	          return errorResponse(400, {
148	            error: 'ambiguous_id',
149	            message: `Ambiguous session ID: ${params.id} matches ${resolution.matches.length} sessions`,
150	            suggestion: 'Provide a longer prefix to uniquely identify the session',
151	          });
152	        }
153	        return errorResponse(404, {
154	          error: 'not_found',
155	          message: `Session not found: ${params.id}`,
156	          suggestion: 'Use GET /api/sessions to list available sessions',
157	        });
158	      }
159	
160	      let events = await readEvents(ctx.specDir, resolution.id);
161	
162	      // Deduplicate phased tool calls
163	      events = deduplicatePhasedToolCalls(events);
164	
165	      // Filter by since_seq if provided (for incremental loading)
166	      const sinceSeq = query.since_seq !== undefined ? parseInt(query.since_seq, 10) : undefined;
167	      if (sinceSeq !== undefined && !isNaN(sinceSeq)) {
168	        events = events.filter(e => e.seq > sinceSeq);
169	      }
170	
171	      return {
172	        events,
173	        total: events.length,
174	      };
175	    }, {
176	      query: t.Object({
177	        since_seq: t.Optional(t.String()),
178	      }),
179	    });
180	}

