571	
572	/**
573	 * Session summary from the daemon API.
574	 */
575	export interface SessionSummary {
576		id: string;
577		status: 'active' | 'completed' | 'abandoned' | 'timed_out' | 'failed';
578		agent_type: string;
579		session_type: 'loop' | 'invocation';
580		started_at: string;
581		ended_at?: string;
582		duration_ms: number;
583		event_count: number;
584		iteration_count: number;
585		tasks_completed: number;
586	}
587	
588	/**
589	 * Spec context with acceptance criteria checklist.
590	 * AC: @ui-session-stream ac-4
591	 */
592	export interface SessionSpecContext {
593		spec_ref: string;
594		title: string;
595		acceptance_criteria: Array<{ id: string; description: string }>;
596	}
597	
598	/**
599	 * Session budget info.
600	 * AC: @ui-session-stream ac-4
601	 */
602	export interface SessionBudget {
603		max_per_cycle: number;
604		started_this_cycle: number;
605	}
606	
607	/**
608	 * Session detail with additional metadata.
609	 * AC: @ui-session-stream ac-4
610	 */
611	export interface SessionDetail extends SessionSummary {
612		task_id?: string;
613		agent_id?: string;
614		trigger?: string;
615		spec_context?: SessionSpecContext | null;
616		budget?: SessionBudget | null;
617	}
618	
619	/**
620	 * A single event from events.jsonl.
621	 */
622	export interface SessionEvent {
623		ts: number;
624		seq: number;
625		type: string;
626		session_id: string;
627		trace_id?: string;
628		data: unknown;
629	}
630	
631	/**
632	 * Fetch all sessions with summaries.
633	 * AC: @ui-session-stream ac-1
634	 */
635	export async function fetchSessions(): Promise<{ items: SessionSummary[]; total: number }> {
636		if (isStaticMode()) {
637			return { items: [], total: 0 };
638		}
639	
640		const response = await fetch(`${API_BASE}/api/sessions`, {
641			headers: getProjectHeaders()
642		});
643		if (!response.ok) {
644			await handleResponseError(response);
645		}
646	
647		return response.json();
648	}
649	
650	/**
651	 * Fetch a single session by ID.
652	 * AC: @ui-session-stream ac-4
653	 */
654	export async function fetchSession(id: string): Promise<SessionDetail> {
655		if (isStaticMode()) {
656			throw new Error('Session data not available in static mode');
657		}
658	
659		const response = await fetch(`${API_BASE}/api/sessions/${id}`, {
660			headers: getProjectHeaders()
661		});
662		if (!response.ok) {
663			await handleResponseError(response);
664		}
665	
666		return response.json();
667	}
668	
669	/**
670	 * Fetch session events (optionally incremental via since_seq).
671	 * AC: @ui-session-stream ac-1, ac-2
672	 */
673	export async function fetchSessionEvents(
674		id: string,
675		sinceSeq?: number
676	): Promise<{ events: SessionEvent[]; total: number }> {
677		if (isStaticMode()) {
678			return { events: [], total: 0 };
679		}
680	
681		const url = new URL(`${API_BASE}/api/sessions/${id}/events`);
682		if (sinceSeq !== undefined) {
683			url.searchParams.set('since_seq', String(sinceSeq));
684		}
685	
686		const response = await fetch(url.toString(), {
687			headers: getProjectHeaders()
688		});
689		if (!response.ok) {
690			await handleResponseError(response);
691		}
692	
693		return response.json();
694	}

